module multi_pipe_4bit(
    input clk, 
    input rst_n, 
    input [3:0] mul_a, 
    input [3:0] mul_b, 
    output [7:0] mul_out
);
// Extension of input signals
    wire [7:0] mul_a_ext, mul_b_ext;
    assign mul_a_ext = {4'b0, mul_a};
    assign mul_b_ext = {4'b0, mul_b};

// Generation of partial products
    wire [7:0] partial_products [3:0];
    genvar i;
    generate
        for(i = 0; i < 4; i = i + 1) begin : gen_partial_products
            assign partial_products[i] = (mul_b_ext[i]) ? (mul_a_ext << i) : 'd0;
        end
    endgenerate

// Registers for storing intermediate sums
    reg [7:0] reg_sum [3:0];
    integer j;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            for(j = 0; j < 4; j = j + 1) begin
                reg_sum[j] <= 0;
            end
        end else begin
            for(j = 0; j < 4; j = j + 1) begin
                reg_sum[j] <= reg_sum[j] + partial_products[j];
            end
        end
    end

// Final product calculation
    reg [7:0] product;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            product <= 0;
        end else begin
            product <= reg_sum[0] + reg_sum[1] + reg_sum[2] + reg_sum[3];
        end
    end

// Output assignment
    assign mul_out = product;
endmodule
